CREATE TABLE IF NOT EXISTS rc_profiles(user_id INTEGER PRIMARY KEY REFERENCES users(id), school TEXT NOT NULL DEFAULT '', bio TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS rc_papers(id TEXT PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL, subject TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', state TEXT NOT NULL DEFAULT 'Draft', public INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rc_versions(id TEXT PRIMARY KEY, paper_id TEXT NOT NULL REFERENCES rc_papers(id), number INTEGER NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(paper_id,number));
CREATE TABLE IF NOT EXISTS rc_keys(version_id TEXT PRIMARY KEY REFERENCES rc_versions(id), content TEXT NOT NULL, source TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rc_files(id TEXT PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL, purpose TEXT NOT NULL, mime TEXT NOT NULL, content BLOB NOT NULL, extracted TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rc_paper_files(paper_id TEXT REFERENCES rc_papers(id), file_id TEXT REFERENCES rc_files(id), PRIMARY KEY(paper_id,file_id));
CREATE TABLE IF NOT EXISTS rc_groups(id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL, owner_id INTEGER NOT NULL REFERENCES users(id), invite TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rc_members(group_id TEXT NOT NULL REFERENCES rc_groups(id), user_id INTEGER NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('Owner','Admin','Member')), PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS rc_group_subjects(group_id TEXT REFERENCES rc_groups(id), subject TEXT NOT NULL, PRIMARY KEY(group_id,subject));
CREATE TABLE IF NOT EXISTS rc_member_subjects(group_id TEXT NOT NULL, user_id INTEGER NOT NULL, subject TEXT NOT NULL, PRIMARY KEY(group_id,user_id,subject), FOREIGN KEY(group_id,user_id) REFERENCES rc_members(group_id,user_id));
CREATE TABLE IF NOT EXISTS rc_subject_requests(id TEXT PRIMARY KEY, group_id TEXT NOT NULL, user_id INTEGER NOT NULL, subject TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pending', response TEXT, reviewed_by INTEGER REFERENCES users(id), reviewed_at TEXT, FOREIGN KEY(group_id,user_id) REFERENCES rc_members(group_id,user_id));
CREATE TABLE IF NOT EXISTS rc_assignments(id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES rc_groups(id), version_id TEXT NOT NULL REFERENCES rc_versions(id), creator_id INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL, due_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rc_attempts(id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), version_id TEXT NOT NULL REFERENCES rc_versions(id), assignment_id TEXT REFERENCES rc_assignments(id), answers TEXT NOT NULL DEFAULT '{}', started_at TEXT NOT NULL, submitted_at TEXT);
CREATE TABLE IF NOT EXISTS rc_submissions(id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL UNIQUE REFERENCES rc_attempts(id), answers TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rc_markings(id TEXT PRIMARY KEY, submission_id TEXT NOT NULL UNIQUE REFERENCES rc_submissions(id), source TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rc_marking_items(id TEXT PRIMARY KEY, marking_id TEXT NOT NULL REFERENCES rc_markings(id), question_id TEXT NOT NULL, awarded REAL NOT NULL, maximum REAL NOT NULL, answer TEXT NOT NULL, correct TEXT NOT NULL, explanation TEXT NOT NULL, confidence TEXT NOT NULL, UNIQUE(marking_id,question_id), CHECK(awarded>=0 AND awarded<=maximum));
CREATE TABLE IF NOT EXISTS rc_challenges(id TEXT PRIMARY KEY, item_id TEXT NOT NULL UNIQUE REFERENCES rc_marking_items(id), student_id INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Challenged', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rc_decisions(id TEXT PRIMARY KEY, challenge_id TEXT NOT NULL REFERENCES rc_challenges(id), reviewer_id INTEGER NOT NULL REFERENCES users(id), old_mark REAL NOT NULL, new_mark REAL NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rc_xp(id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL, reference TEXT NOT NULL, amount INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(user_id,kind,reference));
CREATE TABLE IF NOT EXISTS rc_achievements(user_id INTEGER NOT NULL REFERENCES users(id), achievement TEXT NOT NULL, unlocked_at TEXT NOT NULL, PRIMARY KEY(user_id,achievement));
CREATE TABLE IF NOT EXISTS rc_notifications(id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL, body TEXT NOT NULL, href TEXT NOT NULL, is_read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rc_mistakes(id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), item_id TEXT NOT NULL UNIQUE REFERENCES rc_marking_items(id), subject TEXT NOT NULL, topic TEXT NOT NULL, error_type TEXT NOT NULL DEFAULT 'Concept misunderstanding', corrected_at TEXT);
CREATE TABLE IF NOT EXISTS rc_friends(requester INTEGER NOT NULL REFERENCES users(id), recipient INTEGER NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'Pending', created_at TEXT NOT NULL, PRIMARY KEY(requester,recipient), CHECK(requester<>recipient));
CREATE TABLE IF NOT EXISTS rc_messages(id TEXT PRIMARY KEY, sender_id INTEGER NOT NULL REFERENCES users(id), group_id TEXT REFERENCES rc_groups(id), recipient_id INTEGER REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL, CHECK((group_id IS NULL)<>(recipient_id IS NULL)));
CREATE TABLE IF NOT EXISTS rc_sessions(id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL, subject TEXT NOT NULL, topic TEXT NOT NULL, starts_at TEXT NOT NULL, duration INTEGER NOT NULL, notes TEXT NOT NULL, recurrence TEXT NOT NULL, started_at TEXT, completed_at TEXT, reminded INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS rc_games(id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), game TEXT NOT NULL, subject TEXT NOT NULL, questions TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT, correct INTEGER, total INTEGER, elapsed INTEGER);
CREATE TABLE IF NOT EXISTS rc_battles(id TEXT PRIMARY KEY, challenger INTEGER NOT NULL REFERENCES users(id), opponent INTEGER NOT NULL REFERENCES users(id), version_id TEXT NOT NULL REFERENCES rc_versions(id), mode TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pending', created_at TEXT NOT NULL, challenger_attempt TEXT REFERENCES rc_attempts(id), opponent_attempt TEXT REFERENCES rc_attempts(id));
CREATE TABLE IF NOT EXISTS rc_ratings(paper_id TEXT REFERENCES rc_papers(id), user_id INTEGER REFERENCES users(id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), PRIMARY KEY(paper_id,user_id));
CREATE INDEX IF NOT EXISTS rc_attempts_user ON rc_attempts(user_id,version_id);
CREATE INDEX IF NOT EXISTS rc_notifications_user ON rc_notifications(user_id,is_read);
CREATE INDEX IF NOT EXISTS rc_messages_group ON rc_messages(group_id,created_at);
CREATE INDEX IF NOT EXISTS rc_xp_user ON rc_xp(user_id,created_at);
